WITH eligible AS (SELECT s.* FROM suppliers s WHERE EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ch.brand IS NOT NULL)), scored AS (SELECT *, LAG(rating, 1) OVER (ORDER BY rating, id) AS prev_rating, SUM(rating) OVER (PARTITION BY country) AS country_sum_rating FROM eligible WHERE city IS NOT NULL), with_last AS (SELECT s.*, latest.brand FROM scored s LEFT JOIN LATERAL (SELECT c.brand FROM products c WHERE c.supplier_id = s.id ORDER BY c.price DESC, c.id DESC LIMIT 1) latest ON TRUE), latest AS (SELECT id, country, rating, prev_rating FROM with_last QUALIFY ROW_NUMBER() OVER (PARTITION BY brand ORDER BY prev_rating DESC NULLS LAST, id) = 1) SELECT country, STDDEV_SAMP(rating) AS rating_stddev, AVG(prev_rating) FILTER (WHERE country = 'UK') AS uk_avg_prev_rating, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN country = 'TH' THEN 1 END), 0), 2) AS rating_per_th FROM latest GROUP BY country ORDER BY rating_per_th DESC;
